begin;
select plan(21);
\ir fixtures/captures.sql.inc
set local role cadence_command;
select pg_temp.as_actor(1);
select private.create_private_capture('20000000-0000-4000-8000-000000000001',gen_random_uuid(),null,'Synthetic revisions','Synthetic first body','personal_draft',array['editorial_reuse','excerpt_release']::private.source_purpose[],false,true,null);
select lives_ok($$select private.share_source_original('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.capture_id('Synthetic revisions'),1,1,array['10000000-0000-4000-8000-000000000002']::uuid[],array['editorial_reuse']::private.source_purpose[],true)$$,'explicit original grant binds revision and purpose');
select pg_temp.as_actor(2);
select is(private.read_source_revision('20000000-0000-4000-8000-000000000001',pg_temp.capture_id('Synthetic revisions'),1,'editorial_reuse')->>'body','Synthetic first body','recipient sees only granted revision');
select throws_ok($$select private.share_source_original('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.capture_id('Synthetic revisions'),1,2,array['10000000-0000-4000-8000-000000000003']::uuid[],array['editorial_reuse']::private.source_purpose[],true)$$,'P0001','SOURCE_ACCESS_DENIED','recipient cannot reshare an original');
select throws_ok($$select private.read_source_revision('20000000-0000-4000-8000-000000000001',pg_temp.capture_id('Synthetic revisions'),1,'analytics')$$,'P0001','SOURCE_ACCESS_DENIED','original grant cannot widen use');
select pg_temp.as_actor(1);
select lives_ok($$select private.revise_private_capture('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000020',pg_temp.capture_id('Synthetic revisions'),1,2,null,'Synthetic revisions','Synthetic new private revision','personal_draft',array['editorial_reuse','excerpt_release']::private.source_purpose[],false,true,null)$$,'edit creates an immutable revision and invalidates reuse');
select is(private.revise_private_capture('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000020',pg_temp.capture_id('Synthetic revisions'),1,2,null,'Synthetic revisions','Synthetic new private revision','personal_draft',array['editorial_reuse','excerpt_release']::private.source_purpose[],false,true,null)->>'replayed','true','same edit request is idempotent after version changes');
select is(private.read_source_revision('20000000-0000-4000-8000-000000000001',pg_temp.capture_id('Synthetic revisions'),1,'editorial_reuse')->>'body','Synthetic first body','custodian can still read historical revision');
select throws_ok($$select private.revise_private_capture('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.capture_id('Synthetic revisions'),1,2,null,'Synthetic revisions','stale overwrite','personal_draft',array['editorial_reuse']::private.source_purpose[],false,true,null)$$,'P0001','VERSION_CONFLICT','stale edit cannot overwrite newer text');
select pg_temp.as_actor(2);
select throws_ok($$select private.read_source_revision('20000000-0000-4000-8000-000000000001',pg_temp.capture_id('Synthetic revisions'),2,'editorial_reuse')$$,'P0001','SOURCE_ACCESS_DENIED','old grant cannot unlock new revision');
select pg_temp.as_actor(1);
select private.release_reviewed_excerpt('20000000-0000-4000-8000-000000000001',gen_random_uuid(),pg_temp.capture_id('Synthetic revisions'),2,3,'Synthetic erasable excerpt',array['10000000-0000-4000-8000-000000000002']::uuid[],array['editorial_reuse']::private.source_purpose[],true);
-- Retain only opaque test IDs before erasure removes all user text.
select set_config('test.erase_source',pg_temp.capture_id('Synthetic revisions')::text,true);
select set_config('test.erase_excerpt',pg_temp.excerpt_id('Synthetic erasable excerpt')::text,true);
select lives_ok($$select private.erase_private_source('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000021',current_setting('test.erase_source')::uuid,2,3)$$,'erase purges source revisions and excerpts atomically');
select is(private.erase_private_source('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000021',current_setting('test.erase_source')::uuid,2,3)->>'replayed','true','erasure retry does not duplicate the deletion ledger');
select throws_ok($$select private.read_source_revision('20000000-0000-4000-8000-000000000001',current_setting('test.erase_source')::uuid,2,'editorial_reuse')$$,'P0001','SOURCE_ACCESS_DENIED','deleted capture is unreadable even by custodian');
select pg_temp.as_actor(2);
select throws_ok($$select private.read_reviewed_excerpt('20000000-0000-4000-8000-000000000001',current_setting('test.erase_excerpt')::uuid,'editorial_reuse')$$,'P0001','SOURCE_ACCESS_DENIED','erased parent blocks derivative recipient');
reset role;
select is((select count(*)::integer from private.source_revisions where source_id = current_setting('test.erase_source')::uuid and (title is not null or body is not null)),0,'all revision plaintext is physically cleared');
select is((select count(*)::integer from private.source_excerpts where source_id = current_setting('test.erase_source')::uuid and body is not null),0,'restricted excerpt plaintext is physically cleared');
select is((select count(*)::integer from private.erasure_ledger where source_id = current_setting('test.erase_source')::uuid and state = 'pending'),1,'resource-scoped ledger remains pending external propagation');
select ok(exists(select 1 from private.sources where creator_user_id = '10000000-0000-4000-8000-000000000003' and title = 'Synthetic editor private draft'),'erasure preserves unrelated private material');
select ok(not has_column_privilege('authenticated','private.source_excerpts','source_id','SELECT'),'browser cannot inspect excerpt source lineage');
select ok(not has_column_privilege('cadence_command','private.source_revisions','body','UPDATE'),'server login cannot alter stored revision directly');
select ok(not has_function_privilege('authenticated','private.erase_private_source(uuid,uuid,uuid,bigint,bigint)','EXECUTE'),'browser cannot bypass fresh-session erasure command');
select ok(not has_column_privilege('cadence_command','private.erasure_ledger','reason_code','INSERT'),'server cannot bypass erasure audit by direct ledger insert');
select * from finish();
rollback;
